const webhookBody = $('Webhook: Прием рецепта').first().json.body;
const inventory = Array.isArray(webhookBody.inventory) ? webhookBody.inventory : [];
const byId = new Map(inventory.map((i) => [i.id, i]));
const rawContent = ($input.first().json.choices?.[0]?.message?.content || '{}').trim();
const cleanJson = rawContent.replace(/^```json\s*/i, '').replace(/```$/i, '').trim();
const parsed = JSON.parse(cleanJson);
const meds = (parsed.medications || []).map((med) => {
  const matched = med.matched_medication_id ? byId.get(med.matched_medication_id) : null;
  if (matched && matched.stock_qty > 0) {
    return {
      ...med,
      in_stock: true,
      matched_medication_id: matched.id,
      matched_medication_name: matched.name,
      price_kzt: matched.price_kzt,
      requires_prescription: Boolean(med.requires_prescription || matched.requires_prescription)
    };
  }
  return {
    ...med,
    in_stock: false,
    matched_medication_id: null,
    matched_medication_name: null,
    price_kzt: null
  };
});
const warnings = Array.isArray(parsed.safety_warnings) ? parsed.safety_warnings : [];
const requiresApproval = Boolean(parsed.requires_pharmacist_approval) || meds.some((m) => m.requires_prescription) || warnings.some((w) => w.severity === 'high');
const totalKzt = meds.reduce((acc, m) => acc + (m.in_stock && m.price_kzt ? m.price_kzt : 0), 0);
const orderCode = 'RX-' + Math.floor(1000 + Math.random() * 9000);
return [{
  json: {
    order_code: orderCode,
    patient_name: webhookBody.patient_name,
    patient_phone: webhookBody.patient_phone,
    allergies: webhookBody.allergies || 'Не указаны',
    raw_prescription: webhookBody.prescription_text || 'Фото рецепта',
    status: requiresApproval ? 'pending_approval' : 'ready_for_pickup',
    requires_pharmacist_approval: requiresApproval,
    total_kzt: totalKzt,
    medications: meds,
    safety_warnings: warnings,
    patient_instructions: parsed.patient_instructions || 'Соблюдайте схему приёма, назначенную врачом.',
    disclaimer: 'Информация носит справочный характер и не заменяет консультацию врача. Отпуск рецептурных препаратов выполняется только после подтверждения фармацевтом.',
    created_at: new Date().toISOString()
  }
}];

const formatted = $('Code: Guardrails и расчёт').first().json;
const saved = Array.isArray($input.first().json) ? $input.first().json[0] : $input.first().json;
const orderId = saved?.id || '';
const medLines = (formatted.medications || []).map((m) => `• ${m.prescribed_name} — ${m.in_stock ? m.price_kzt + ' ₸' : 'нет в наличии' + (m.alternative_suggestion ? ' (аналог: ' + m.alternative_suggestion + ')' : '')}`).join('
');
const warnLines = (formatted.safety_warnings || []).map((w) => `⚠️ [${w.severity.toUpperCase()}] ${w.title}: ${w.details}`).join('
');
const tgText = `🧾 Новый заказ ${formatted.order_code}
👤 Пациент: ${formatted.patient_name} (${formatted.patient_phone})
🚫 Аллергии: ${formatted.allergies}

💊 Препараты:
${medLines}

💰 Итого: ${formatted.total_kzt} ₸` + (warnLines ? `

${warnLines}` : '');
return [{ json: { ...formatted, order_id: orderId, telegram_text: tgText } }];
